-- =====================================================================
--  big.sql: large tables for Phase 5 (indexes and EXPLAIN)
--
--  Load it AFTER practice.sql, into the same database:
--    psql -U postgres -d practice -f big.sql
--  It takes a few seconds. Reload it any time to get a clean copy.
--
--  The data is generated by formulas (no random()), so every machine gets
--  exactly the same rows, and the same query plans as the website shows.
--    big_customers   20,000 rows   about 2% live in Dubai (UAE) and 2% in London (UK):
--                                  city and country depend on each other
--                                  emails: 1 in 5 has upper-case letters
--    big_orders     200,000 rows   one every ~5 minutes from 1 Jan 2024, in time order;
--                                  customer 42 is a "hot" customer with ~5,000 orders;
--                                  the newest 1,000 are pending and 2,000 shipped;
--                                  customer_id has a foreign key but NO index
--    big_events     100,000 rows   app events as JSONB (1% are errors)
--  Only primary keys exist. Every other index is yours to create.
-- =====================================================================

DROP TABLE IF EXISTS big_events, big_orders, big_customers CASCADE;

-- Same plans on every machine: no parallel workers and no JIT compilation.
-- Session 53 explains both settings and turns them back on.
DO $$ BEGIN
  EXECUTE format('ALTER DATABASE %I SET max_parallel_workers_per_gather = 0', current_database());
  EXECUTE format('ALTER DATABASE %I SET jit = off', current_database());
END $$;
SET max_parallel_workers_per_gather = 0;
SET jit = off;

CREATE TABLE big_customers (
  customer_id INTEGER PRIMARY KEY,
  email       TEXT NOT NULL,
  full_name   TEXT NOT NULL,
  city        TEXT NOT NULL,
  country     TEXT NOT NULL,
  signup_date DATE NOT NULL,
  is_active   BOOLEAN NOT NULL
);

INSERT INTO big_customers
SELECT g,
       CASE WHEN g % 5 = 0 THEN 'User' || g || '@Mail.Test' ELSE 'user' || g || '@mail.test' END,
       (ARRAY['Aarav', 'Diya', 'Kabir', 'Ananya', 'Ishaan', 'Saanvi', 'Vivaan', 'Myra', 'Reyansh', 'Kiara'])[1 + g % 10]
         || ' ' ||
       (ARRAY['Shah', 'Menon', 'Khan', 'Gupta', 'Reddy', 'Pillai', 'Bose', 'Chawla', 'Jain', 'Sethi', 'Rao', 'Ali'])[1 + (g / 10) % 12],
       c.city,
       CASE c.city WHEN 'Dubai' THEN 'UAE' WHEN 'London' THEN 'UK' ELSE 'India' END,
       DATE '2023-01-01' + (g * 17) % 1095,
       g % 10 <> 0
FROM generate_series(1, 20000) AS g
CROSS JOIN LATERAL (
  SELECT CASE WHEN g % 50 = 7  THEN 'Dubai'
              WHEN g % 50 = 13 THEN 'London'
              ELSE (ARRAY['Mumbai', 'Delhi', 'Bengaluru', 'Pune', 'Hyderabad', 'Chennai', 'Kolkata', 'Jaipur'])[1 + g % 8]
         END AS city
) AS c;

CREATE TABLE big_orders (
  order_id      INTEGER PRIMARY KEY,
  customer_id   INTEGER NOT NULL REFERENCES big_customers (customer_id),   -- no index!
  created_at    TIMESTAMPTZ NOT NULL,
  status        TEXT NOT NULL,
  total         NUMERIC(10, 2) NOT NULL,
  shipping_city TEXT NOT NULL,
  coupon        TEXT                                                        -- mostly NULL
);

INSERT INTO big_orders
SELECT g,
       CASE WHEN g % 40 = 0 THEN 42 ELSE 1 + (g * 7919) % 20000 END,
       TIMESTAMPTZ '2024-01-01 00:00+05:30' + (g - 1) * INTERVAL '5 minutes' + ((g * 13) % 300) * INTERVAL '1 second',
       CASE WHEN g > 199000            THEN 'pending'
            WHEN g > 197000            THEN 'shipped'
            WHEN (g * 31) % 100 < 3    THEN 'cancelled'
            ELSE 'delivered' END,
       (100 + (g * 7907) % 49900 + (g % 100) / 100.0)::numeric(10, 2),
       (ARRAY['Mumbai', 'Delhi', 'Bengaluru', 'Pune', 'Hyderabad', 'Chennai', 'Kolkata', 'Jaipur'])[1 + (g * 3) % 8],
       CASE WHEN g % 50 = 0 THEN 'SAVE10' WHEN g % 333 = 0 THEN 'FEST20' END
FROM generate_series(1, 200000) AS g;

CREATE TABLE big_events (
  event_id    INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL,
  payload     JSONB NOT NULL
);

INSERT INTO big_events
SELECT g,
       1 + (g * 6007) % 20000,
       TIMESTAMPTZ '2025-06-01 00:00+05:30' + (g - 1) * INTERVAL '2 minutes' + ((g * 7) % 120) * INTERVAL '1 second',
       CASE WHEN g % 100 = 0 THEN
              jsonb_build_object('type', 'app_error',
                                 'code', (ARRAY['PAYMENT_TIMEOUT', 'OUT_OF_STOCK', 'NETWORK'])[1 + (g / 100) % 3],
                                 'device', jsonb_build_object('os', (ARRAY['android', 'ios', 'web'])[1 + g % 3]))
            WHEN g % 100 < 5 THEN
              jsonb_build_object('type', 'checkout', 'order_id', g,
                                 'device', jsonb_build_object('os', (ARRAY['android', 'ios', 'web'])[1 + g % 3]))
            WHEN g % 100 < 15 THEN
              jsonb_build_object('type', 'add_to_cart', 'product_id', 1 + g % 15, 'qty', 1 + g % 3,
                                 'device', jsonb_build_object('os', (ARRAY['android', 'ios', 'web'])[1 + g % 3]))
            WHEN g % 100 < 30 THEN
              jsonb_build_object('type', 'search',
                                 'query', (ARRAY['laptop', 'mouse', 'headphones', 'coffee', 'lamp', 'desk'])[1 + g % 6],
                                 'device', jsonb_build_object('os', (ARRAY['android', 'ios', 'web'])[1 + g % 3]))
            ELSE
              jsonb_build_object('type', 'page_view', 'page', '/p/' || (1 + g % 15),
                                 'device', jsonb_build_object('os', (ARRAY['android', 'ios', 'web'])[1 + g % 3]))
       END
FROM generate_series(1, 100000) AS g;

-- ANALYZE normally reads a random sample of 30,000 rows, so statistics (and
-- sometimes plans) differ a little between machines. A higher target on one
-- column makes ANALYZE read every row: identical statistics everywhere.
-- (Session 52 explains statistics targets.)
ALTER TABLE big_orders ALTER COLUMN order_id SET STATISTICS 1000;
ALTER TABLE big_events ALTER COLUMN event_id SET STATISTICS 400;

VACUUM ANALYZE big_customers, big_orders, big_events;
